"""Build the frontend-facing API reference package.

    bench --site test.localhost execute \
        yob_storefront.tests.fixtures.build_frontend_reference.run

Emits, under ``/tmp/yob_reference_build/reference/api/``:

    openapi.json
    postman_collection.json
    live/README.md
    live/verified-responses.json

Signatures, verbs, guest status and required parameters come from Frappe's own
registry via ``inspect.signature`` -- never from a hand-maintained list, because
a hand-maintained list is what drifts. Payment response examples come from
``capture_payment_contracts``, which executes the real endpoints inside a
rolled-back savepoint with a faked provider.

Verification levels, used honestly:

    wire   -- observed over HTTP through the edge proxy
    test   -- real endpoint executed in-process, savepoint-isolated, provider
              faked; no HTTP round trip and no live provider
    source -- read from the implementation; not executed
"""

import importlib
import inspect
import json
import pathlib
import pkgutil

import frappe

ALLOWED_SITES = {"test.localhost"}
BUILD = pathlib.Path("/tmp/yob_reference_build/reference/api")
PREVIOUS = pathlib.Path("/home/shayona/yob-frontend/reference/api/live/verified-responses.json")
CAPTURED = pathlib.Path("/tmp/yob_payment_contracts.json")

BASE_URL = "http://storefront.local:8080"


# =========================================================
# ENDPOINT INTROSPECTION
# =========================================================

def endpoints():
    found = []
    for app in ("yob_auth", "yob_storefront"):
        pkg = importlib.import_module(f"{app}.api")
        for mod_info in pkgutil.iter_modules(pkg.__path__):
            mod = importlib.import_module(f"{app}.api.{mod_info.name}")
            for name, fn in vars(mod).items():
                if not callable(fn) or not getattr(fn, "__module__", "").startswith(app):
                    continue
                if fn not in frappe.whitelisted:
                    continue
                try:
                    sig = inspect.signature(fn)
                except (TypeError, ValueError):
                    continue
                params = [
                    {"name": p.name,
                     "required": p.default is inspect.Parameter.empty,
                     "default": None if p.default is inspect.Parameter.empty else p.default}
                    for p in sig.parameters.values()
                    if p.name != "auth_context"
                ]
                found.append({
                    "path": f"{app}.api.{mod_info.name}.{name}",
                    "methods": list(
                        frappe.allowed_http_methods_for_whitelisted_func.get(fn) or []
                    ) or ["GET", "POST"],
                    "guest": fn in frappe.guest_methods,
                    "params": params,
                    "summary": (inspect.getdoc(fn) or "").split("\n")[0],
                })
    return sorted(found, key=lambda e: e["path"])


