# =========================================================
# OPENAPI
# =========================================================

def build_openapi(eps, captured):
    paths = {}

    for ep in eps:
        verb = "post" if "POST" in ep["methods"] else "get"
        dotted = ep["path"]
        success_key, error_key = PAYMENT_EXAMPLE_KEYS.get(dotted, (None, None))

        statuses = {
            "200": {"description": "Success envelope",
                    "content": {"application/json": {
                        "schema": {"$ref": "#/components/schemas/Success"}}}},
            "4XX": {"description": "Error envelope",
                    "content": {"application/json": {
                        "schema": {"$ref": "#/components/schemas/Error"}}}},
        }

        if success_key and success_key in captured:
            body = captured[success_key]
            code = str(body["__http_status__"])
            entry = {"description": "Success envelope",
                     "content": {"application/json": {
                         "schema": {"$ref": "#/components/schemas/Success"},
                         "example": {k: v for k, v in body.items()
                                     if k != "__http_status__"}}}}
            statuses[code] = entry

        # proceed_to_payment answers 201 on creation and 200 on reuse.
        if dotted.endswith("checkout.proceed_to_payment"):
            reuse = captured.get("proceed_to_payment.reused")
            if reuse:
                statuses["200"] = {
                    "description": "Existing open obligation reused",
                    "content": {"application/json": {
                        "schema": {"$ref": "#/components/schemas/Success"},
                        "example": {k: v for k, v in reuse.items()
                                    if k != "__http_status__"}}}}

        if error_key and error_key in captured:
            body = captured[error_key]
            statuses[str(body["__http_status__"])] = {
                "description": "Error envelope",
                "content": {"application/json": {
                    "schema": {"$ref": "#/components/schemas/Error"},
                    "example": {k: v for k, v in body.items()
                                if k != "__http_status__"}}}}

        op = {
            "summary": ep["summary"] or dotted.rsplit(".", 1)[-1],
            "operationId": dotted,
            "tags": [dotted.split(".")[0]],
            "security": [] if ep["guest"] else [{"sessionCookie": []}],
            "responses": statuses,
        }

        if dotted in PAYMENT_NOTES:
            op["description"] = "\n".join(f"- {n}" for n in PAYMENT_NOTES[dotted])

        if verb == "post":
            op["requestBody"] = {"required": bool(ep["params"]),
                                 "content": {"application/json": {"schema": {
                "type": "object",
                "required": [p["name"] for p in ep["params"] if p["required"]],
                "properties": {
                    p["name"]: {"description": f"default: {p['default']!r}"}
                    for p in ep["params"]},
            }}}}
            if not ep["guest"]:
                op["parameters"] = [{
                    "name": "X-Frappe-CSRF-Token", "in": "header", "required": True,
                    "schema": {"type": "string"},
                    "description": "Frappe CSRF token from login or get_session_context.",
                }]
        else:
            op["parameters"] = [
                {"name": p["name"], "in": "query", "required": p["required"],
                 "schema": {"type": "string"}}
                for p in ep["params"]
            ]

        paths[f"/api/method/{dotted}"] = {verb: op}

    return {
        "openapi": "3.1.0",
        "info": {
            "title": "YOB Storefront & Auth API",
            "version": "2.0.0",
            "description": (
                "Frappe RPC-style API. Every response is wrapped by Frappe in an "
                "outer `message` object; the inner body is the YOB envelope "
                "(`data` plus optional `notice`/`meta` on success, `errors[]` on "
                "failure). There is NO `success` boolean: branch on HTTP status, "
                "then on `errors[0].code`.\n\n"
                "Version 2.0.0 reflects the Payment Lifecycle Phase 2B backend. "
                "The payment contract changed materially: a Payment Request is an "
                "immutable obligation, `get_checkout_data` serves both Cart-backed "
                "and Sales-Order-backed sources, and `process_payment` commits the "
                "cart to exactly one Draft Sales Order before contacting any "
                "provider.\n\n"
                "CSRF is Frappe's own: non-GET authenticated requests need "
                "`X-Frappe-CSRF-Token`. Authenticated calls must traverse the edge "
                "proxy that sets `X-YOB-Original-Host`. Guest payment endpoints "
                "are authorized by the checkout token or by Razorpay's HMAC "
                "signature and need no session."
            ),
        },
        "servers": [{"url": BASE_URL}],
        "components": {
            "securitySchemes": {
                "sessionCookie": {"type": "apiKey", "in": "cookie", "name": "sid"}},
            "schemas": {
                "Success": {"type": "object", "properties": {"message": {
                    "type": "object",
                    "required": ["data"],
                    "properties": {"data": {}, "notice": {"type": "string"},
                                   "meta": {"type": "object"}}}}},
                "Error": {"type": "object", "properties": {"message": {
                    "type": "object",
                    "required": ["errors"],
                    "properties": {"errors": {"type": "array", "items": {
                        "type": "object",
                        "required": ["code", "detail"],
                        "properties": {
                            "code": {"type": "string"},
                            "detail": {"type": "string"},
                            "field": {"type": "string"},
                            "details": {"type": "object"}}}}}}}},
            },
        },
        "paths": paths,
    }


