POSTMAN_BODIES = {
    "yob_storefront.api.payment.process_payment": {
        "Pay Later": {"token": "{{checkout_token}}", "payment_method": "Pay Later"},
        "Razorpay": {"token": "{{checkout_token}}", "payment_method": "Razorpay"},
    },
    "yob_storefront.api.payment.verify_payment": {
        None: {"razorpay_order_id": "{{razorpay_order_id}}",
               "razorpay_payment_id": "{{razorpay_payment_id}}",
               "razorpay_signature": "{{razorpay_signature}}"},
    },
}

POSTMAN_QUERY = {
    "yob_storefront.api.payment.get_checkout_data": {"token": "{{checkout_token}}"},
    "yob_storefront.api.payment_method.get_payment_methods": {"order_amount": "500"},
}


def build_postman(eps):
    items = []

    for ep in eps:
        dotted = ep["path"]
        verb = "POST" if "POST" in ep["methods"] else "GET"

        variants = POSTMAN_BODIES.get(dotted, {None: None})

        for label, body in variants.items():
            headers = [{"key": "Content-Type", "value": "application/json"}]
            if verb == "POST" and not ep["guest"]:
                headers.append({"key": "X-Frappe-CSRF-Token", "value": "{{csrf_token}}"})

            query = POSTMAN_QUERY.get(dotted, {})
            raw = f"{{{{base_url}}}}/api/method/{dotted}"
            if query:
                raw += "?" + "&".join(f"{k}={v}" for k, v in query.items())

            req = {
                "method": verb,
                "header": headers,
                "url": {"raw": raw, "host": ["{{base_url}}"],
                        "path": ["api", "method", dotted],
                        "query": [{"key": k, "value": v} for k, v in query.items()]},
            }

            if verb == "POST":
                payload = body if body is not None else {
                    p["name"]: "" for p in ep["params"]}
                req["body"] = {"mode": "raw", "raw": json.dumps(payload, indent=2)}

            items.append({"name": dotted + (f" ({label})" if label else ""),
                          "request": req})

    return {
        "info": {
            "name": "YOB Storefront & Auth API (Phase 2B)",
            "description": (
                "Session: run login_with_password first, keep the sid cookie, and "
                "put the returned csrf_token into the {{csrf_token}} variable.\n\n"
                "No real credentials, session ids, checkout tokens or Razorpay "
                "secrets are stored in this collection -- every such value is a "
                "placeholder variable you fill in locally."
            ),
            "schema": "https://schema.getpostman.com/json/collection/v2.1.0/collection.json",
        },
        "variable": [
            {"key": "base_url", "value": BASE_URL},
            {"key": "csrf_token", "value": "", "description": "From login response."},
            {"key": "checkout_token", "value": "",
             "description": "From proceed_to_payment `data.token`. A live bearer credential -- never commit a real one."},
            {"key": "razorpay_order_id", "value": ""},
            {"key": "razorpay_payment_id", "value": ""},
            {"key": "razorpay_signature", "value": ""},
        ],
        "item": items,
    }


